// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(amount <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        // Drive the contract through its public surface, ending with sendTo
        c.sendTo(receiver, amount);
        // General rule: contract balance remains unchanged
        assertTrue(address(c).balance == balanceBefore);
    }
}

